import { useSetRecoilState } from "recoil";
import IToDo from "../interfaces/IToDo";
import { Category, toDoListState } from "../atoms";
import { ButtonHTMLAttributes, ReactElement, useState } from "react";
import styled from "styled-components";

const ItemContainer = styled.li`
	display: flex;
	justify-content: space-between;
	align-items: center;
	padding: 0px 12px;
	margin-bottom: 12px;
	color: ${(props) => props.theme.textColors.normal};
	font-size: 18px;
`;



const Button = styled.button`
	text-align: center;
	font-size: 14px;
	font-weight: 500;
	padding: 4px 12px;
	border-radius: 8px; 

`;

const CategoryButton = styled(Button)`
	background-color: ${(props) => props.theme.bgColors.reversed};
	color: ${(props) => props.theme.textColors.reversed};
`; 

const DeleteButton = styled(Button)`
	/* background-color: ${(props) => props.theme.brandColors.primary};	 */
	background-color: #ff000099;	
	color: ${(props) => props.theme.textColors.reversed};	
`;

const DropDownContainer = styled.div`
	display	: flex;
	flex-direction: column;
	justify-content: end;
	position: relative;
`;

const Dropdown = styled.ul`
  position: absolute;
	top: 100%;
	right: 0%;
  margin-top: 4px;
  background: white;
  border-radius: 8px;
  padding: 8px;

  display: flex;
	flex-direction: column;
	align-items: end;
	gap: 4px;
`;

const DropdownOption = styled(Button)`
  /* padding: 4px 6px; */
  cursor: pointer;
`;

function ToDo({ id, text, category }: IToDo) {
	const [isOpen, setIsOpen] = useState(false);
	const setToDoList = useSetRecoilState(toDoListState);

	const updateToDoCategory = (newCategory: IToDo["category"]) => {
		setToDoList(oldToDoList => {
			const targetIdx = oldToDoList.findIndex( todo => todo.id === id );
			const newToDo = {id, text, category: newCategory}
			return [
				...oldToDoList.slice(0, targetIdx), 
				newToDo, 
				...oldToDoList.slice(targetIdx+1)
			];
		});
		setIsOpen(false);
		// setToDoList(oldToDoList => {
		// 	const newList = oldToDoList.map( todo => {
		// 		return todo.id === id ? {id, text: text, category: newCategory} : todo
		// 	});

		// 	return newList;
		// });
	};

	const deleteTodo = () => {
		setToDoList(oldToDoList => {
			const targetIdx = oldToDoList.findIndex( todo => todo.id === id );
			return [
				...oldToDoList.slice(0, targetIdx), 
				...oldToDoList.slice(targetIdx+1)
			];
		});
	}

	const handleSelectCategory = (newCategory: Category) => {
    setToDoList((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, category: newCategory } : todo
      )
    );
    setIsOpen(false);
  };


	const categories = Object.values(Category);

	return (
		<ItemContainer>
			<span>{text}</span>
			<div style={{display:"flex", gap:"6px"}}>
				<DropDownContainer>
					{categories.map((c) => (
						category === c && <Button onClick={() => setIsOpen(true)}>{c}</Button>
						// category === c && <Button onClick={() => updateToDoCategory(Category.TO_DO)}>{c}</Button>
					))}
					{/* 드롭다운 */}
					{isOpen && (
						<Dropdown>
							{categories.map((c) => (
								<DropdownOption onClick={() => updateToDoCategory(c)}>{c}</DropdownOption>
							))}
						</Dropdown>
					)}	
				</DropDownContainer>
				<DeleteButton onClick={deleteTodo}>x</DeleteButton>
			</div>

		</ItemContainer>
	);
}

export default ToDo;
